   "tipus": "Concurrencia competitiva - canónica",
   "directa": false,
   "resum": "Contribuir a la financiación de los gastos derivados de la realización de las actividades ordinarias propias de las OPA de la isla de Menorca, incluyendo el asesoramiento a sus asociados y la organización de la gestión de los residuos plásticos agrícolas de las explotaciones, correspondientes al periodo comprendido entre el 1 de enero y el 31 de diciembre de 2026.",
   "requisits": [
    "Organizaciones profesionales agrarias legalmente constituidas que tengan el domicilio social y ámbito de actuación dentro del territorio de Menorca y un funcionamiento interno real y democrático. En este sentido, quedan excluidas las organizaciones que no lleven a cabo los procesos electorales previstos en sus estatutos."
   ],
