   "resum": "Regular las ayudas para la transformación de los centros educativos de Menorca de todas las etapas y niveles educativos, tanto públicos como privados, en centros más sostenibles. Tiene por finalidad el impulso de iniciativas para la implementación de actuaciones de educación para la sostenibilidad.",
   "requisits": [
    "Pueden concurrir a esta convocatoria los centros educativos de Menorca de titularidad pública o privada y que cumplan los siguientes requisitos: a) Estar debidamente constituidos como centro educativo y estar inscritos en el Registro de Centros docentes no Universitarios, creado por el Decreto 59/2003, de 13 de junio. b) Estar ubicados en la isla de Menorca."
   ],
